// AI background images for scenes, generated by packages/image-gen (Python, local GPU or FAL).
// Free: local generation costs no credits; the Cloud preset bills the owner's own FAL key.
import { THEME_IDS } from './VideoTheme';
import crypto from 'node:crypto';
import mongoose from 'mongoose';
import { spawn } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { Job } from '../models/Job';
import { Scene } from '../models/Scene';
import { ImageGenStat, SceneImage } from '../models/SceneImage';

export class ImageGenError extends Error { constructor(public readonly code: string, public readonly status = 400) { super(code); } }

export const imageGenDir = () => resolve(process.env.IMAGE_GEN_DIR || resolve(__dirname, '../../../../packages/image-gen'));
export const imagePython = () => resolve(imageGenDir(), '.venv', process.platform === 'win32' ? 'Scripts/python.exe' : 'bin/python');
export const imageCacheDir = () => resolve(process.env.IMAGE_GEN_CACHE_DIR || resolve(imageGenDir(), 'cache'));

export interface PresetConfig {
  id: string; label: string; kind: 'local' | 'fal'; model: string; steps: number; width: number; height: number;
  estimateSeconds: number; downloadGB: number; requiresEnv?: string; [key: string]: unknown;
}
interface PresetFile { default: string; fallbackOrder: string[]; presets: PresetConfig[]; output: { width: number; height: number } }

let presetCache: PresetFile | null = null;
export function presetFile(): PresetFile {
  if (!presetCache) presetCache = JSON.parse(readFileSync(resolve(imageGenDir(), 'presets.json'), 'utf8')) as PresetFile;
  return presetCache;
}
/** Part of every image URL. Bump it when response headers change, so browsers drop cached copies. */
export const IMAGE_URL_REV = 2;
/** Image style follows the video theme (packages/image-gen/style.py). Old runs stored "veltrix" = cosmic. */
export const DEFAULT_THEME = 'cosmic';
const THEMES = new Set<string>(THEME_IDS);

/** Environment for the Python worker: only what it needs (no database or JWT secrets). */
export function pythonEnv(): NodeJS.ProcessEnv {
  const keep = ['SYSTEMROOT', 'SystemRoot', 'WINDIR', 'PATH', 'Path', 'TEMP', 'TMP', 'USERPROFILE', 'HOME', 'LOCALAPPDATA', 'APPDATA', 'HF_HOME', 'HF_HUB_CACHE', 'HF_TOKEN', 'FAL_KEY', 'FAL_AI_API_KEY', 'CUDA_VISIBLE_DEVICES', 'PYTORCH_CUDA_ALLOC_CONF'];
  const env: NodeJS.ProcessEnv = { PYTHONUTF8: '1', PYTHONIOENCODING: 'utf-8' };
  for (const key of keep) if (process.env[key]) env[key] = process.env[key];
  env.PYTORCH_CUDA_ALLOC_CONF ||= 'expandable_segments:True';
  return env;
}

export type ImageEvent = { type: string; [key: string]: any };

/** Runs generate.py, calling onEvent for each EVENT line. Resolves with the exit code. */
export function runImageWorker(args: string[], onEvent: (event: ImageEvent) => void, signal?: AbortSignal): Promise<number> {
  return new Promise((ok, fail) => {
    if (!existsSync(imagePython())) return fail(new ImageGenError('IMAGE_GEN_NOT_INSTALLED', 503));
    const child = spawn(imagePython(), [resolve(imageGenDir(), 'generate.py'), ...args], { cwd: imageGenDir(), env: pythonEnv(), windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let buffer = '';
    const abort = () => child.kill();
    signal?.addEventListener('abort', abort, { once: true });
    child.stdout.on('data', (chunk) => {
      buffer += chunk;
      let index;
      while ((index = buffer.indexOf('\n')) >= 0) {
        const line = buffer.slice(0, index).trim(); buffer = buffer.slice(index + 1);
        if (!line.startsWith('EVENT ')) continue;
        try { onEvent(JSON.parse(line.slice(6))); } catch { /* ignore malformed line */ }
      }
    });
    let stderr = '';
    child.stderr.on('data', (chunk) => { stderr = (stderr + chunk).slice(-4000); });
    child.on('error', () => fail(new ImageGenError('IMAGE_GEN_UNAVAILABLE', 503)));
    child.on('close', (code) => {
      signal?.removeEventListener('abort', abort);
      if (code && code !== 0 && !signal?.aborted) console.error('[image-gen]', stderr.split('\n').filter(Boolean).slice(-3).join(' | ').slice(0, 500));
      ok(code ?? 1);
    });
  });
}

type StatusValue = Record<string, { installed: boolean; available: boolean; haveGB?: number }> & { __stack?: { ready: boolean; missing: string[] } };
let statusCache: { at: number; value: StatusValue } | null = null;
/** Which presets are downloaded / usable. Cached for 30 s (it scans the model cache). */
export async function presetStatus(force = false) {
  if (!force && statusCache && Date.now() - statusCache.at < 30_000) return statusCache.value;
  const value: StatusValue = {};
  try {
    await runImageWorker(['status'], (event) => {
      if (event.type !== 'status') return;
      for (const p of event.presets) value[p.id] = { installed: !!p.installed, available: !!p.available, haveGB: p.haveGB };
      value.__stack = event.stack;
    });
  } catch { /* not installed: every preset reports unavailable below */ }
  // Cache a "not ready" answer only briefly, so a finished install shows up quickly.
  statusCache = { at: value.__stack?.ready ? Date.now() : Date.now() - 25_000, value };
  return value;
}

/** True when the Python worker and torch/diffusers are installed. */
export async function localStackReady() {
  if (process.env.NODE_ENV === 'test' && process.env.IMAGE_GEN_ASSUME_READY === '1') return true; // tests use a fake runner
  return existsSync(imagePython()) && !!(await presetStatus()).__stack?.ready;
}

/** Presets for the form: measured average time (or the default estimate), download needs, availability. */
export async function listPresets() {
  const file = presetFile();
  const [status, stats] = await Promise.all([presetStatus(), ImageGenStat.find().lean()]);
  const measured = new Map(stats.map((s) => [s.preset, s]));
  return {
    default: file.default,
    installed: existsSync(imagePython()) && !!status.__stack?.ready,
    missing: status.__stack?.missing ?? [],
    presets: file.presets
      .filter((p) => !p.requiresEnv || !!process.env[p.requiresEnv] || (p.requiresEnv === 'FAL_KEY' && !!process.env.FAL_AI_API_KEY))
      .map((p) => {
        const stat = measured.get(p.id);
        return {
          id: p.id, label: p.label, kind: p.kind, isDefault: p.id === file.default,
          estimateSeconds: stat && stat.count > 0 ? Math.round(stat.avgSeconds * 10) / 10 : p.estimateSeconds,
          measured: !!stat && stat.count > 0,
          installed: p.kind === 'fal' ? true : !!status[p.id]?.installed,
          downloadGB: p.downloadGB,
        };
      }),
  };
}

/** Running average of generation seconds per preset (cache hits are not counted). */
export async function recordImageTime(preset: string, seconds: number) {
  if (!(seconds > 0)) return;
  const stat = await ImageGenStat.findOneAndUpdate({ preset }, { $setOnInsert: { count: 0, avgSeconds: 0 } }, { upsert: true, new: true });
  const count = stat.count + 1;
  await ImageGenStat.updateOne({ _id: stat._id, count: stat.count }, { $set: { count, avgSeconds: stat.avgSeconds + (seconds - stat.avgSeconds) / count } });
}

/** One seed per video (from the project), plus the scene index: consistent style across scenes. */
export const baseSeed = (projectId: mongoose.Types.ObjectId | string) => parseInt(crypto.createHash('sha256').update(String(projectId)).digest('hex').slice(0, 7), 16);
export const sceneSeed = (projectId: mongoose.Types.ObjectId | string, order: number, attempt: number) => baseSeed(projectId) + order + attempt * 7919;

export const validPreset = (preset: unknown) => {
  const id = typeof preset === 'string' && preset ? preset : presetFile().default;
  const config = presetFile().presets.find((p) => p.id === id);
  if (!config) throw new ImageGenError('IMAGE_PRESET_UNKNOWN');
  if (config.requiresEnv && !process.env[config.requiresEnv] && !(config.requiresEnv === 'FAL_KEY' && process.env.FAL_AI_API_KEY)) throw new ImageGenError('IMAGE_PRESET_UNAVAILABLE', 409);
  return id;
};
export const validTheme = (theme: unknown) => (typeof theme === 'string' && THEMES.has(theme) ? theme : DEFAULT_THEME);

/**
 * Queues image generation for scenes of a project. Scenes without an image prompt are skipped
 * (they keep the Pexels / gradient background). Returns null when there is nothing to make.
 */
export async function createImageJob(input: {
  ownerId: mongoose.Types.ObjectId; projectId: mongoose.Types.ObjectId; preset: string; theme?: string;
  sceneIds?: string[]; regenerate?: boolean; runId?: mongoose.Types.ObjectId;
}) {
  const preset = validPreset(input.preset);
  const theme = validTheme(input.theme);
  const filter: any = { projectId: input.projectId };
  if (input.sceneIds) filter._id = { $in: input.sceneIds.filter((id) => mongoose.isObjectIdOrHexString(id)) };
  const scenes = await Scene.find(filter).sort({ order: 1 }).select('order imagePrompt').lean();
  const targets: string[] = [];
  for (const scene of scenes) {
    const existing = await SceneImage.findOne({ sceneId: scene._id });
    const prompt = existing?.promptEdited && existing.preset !== 'wikimedia' ? existing.prompt : String(scene.imagePrompt || '').trim();
    if (!prompt) continue;
    if (existing && (existing.status === 'PENDING' || existing.status === 'GENERATING')) throw new ImageGenError('IMAGE_ALREADY_GENERATING', 409);
    if (existing && existing.status === 'READY' && !input.regenerate && existing.preset === preset && existing.prompt === prompt) continue;
    // A real archival photo (services/RealPhotos.ts) stays unless the user asks to regenerate this scene.
    if (existing && existing.status === 'READY' && existing.preset === 'wikimedia' && !input.regenerate) continue;
    const attempt = existing ? existing.attempt + (input.regenerate ? 1 : 0) : 0;
    await SceneImage.updateOne({ sceneId: scene._id }, {
      $set: { ownerId: input.ownerId, projectId: input.projectId, order: scene.order, status: 'PENDING', prompt, preset, attempt, seed: sceneSeed(input.projectId, scene.order, attempt), error: null, downgradedFrom: null, credit: null, sourceUrl: null },
      $setOnInsert: { promptEdited: false },
    }, { upsert: true });
    targets.push(String(scene._id));
  }
  // Include dedicated Thumbnail (order: 0) if run has thumbnailPrompt
  if (input.runId) {
    const { AutoVideoRun } = await import('../models/AutoVideoRun');
    const run = await AutoVideoRun.findById(input.runId);
    if (run?.thumbnailPrompt) {
      if (!run.thumbnailSceneId) {
        run.thumbnailSceneId = new mongoose.Types.ObjectId();
        await run.save();
      }
      const thumbId = run.thumbnailSceneId;
      const isTargeted = !input.sceneIds || input.sceneIds.includes(String(thumbId));
      if (isTargeted) {
        const existingThumb = await SceneImage.findOne({ sceneId: thumbId });
        const thumbPrompt = existingThumb?.promptEdited ? existingThumb.prompt : run.thumbnailPrompt;
        if (!existingThumb || input.regenerate || existingThumb.status !== 'READY' || existingThumb.preset !== preset) {
          const attempt = existingThumb ? existingThumb.attempt + (input.regenerate ? 1 : 0) : 0;
          await SceneImage.updateOne({ sceneId: thumbId }, {
            $set: {
              ownerId: input.ownerId,
              projectId: input.projectId,
              order: 0,
              status: 'PENDING',
              prompt: thumbPrompt,
              preset,
              attempt,
              seed: sceneSeed(input.projectId, 0, attempt),
              error: null,
              downgradedFrom: null,
            },
            $setOnInsert: { promptEdited: false },
          }, { upsert: true });
          targets.unshift(String(thumbId));
        }
      }
    }
  }

  if (!targets.length) return null;
  const job = await Job.create({
    ownerId: input.ownerId, type: 'IMAGE_GEN', status: 'QUEUED', idempotencyKey: `image-${crypto.randomUUID()}`,
    payload: { projectId: input.projectId, runId: input.runId ?? null, preset, theme, sceneIds: targets, cancelRequested: false },
  });
  await SceneImage.updateMany({ sceneId: { $in: targets } }, { $set: { jobId: job._id } });
  return job;
}

/** Stops a running image job. Scenes not finished yet fall back to Pexels / gradient. */
export async function cancelImageJob(ownerId: mongoose.Types.ObjectId, jobId: mongoose.Types.ObjectId | string) {
  const job = await Job.findOne({ _id: jobId, ownerId, type: 'IMAGE_GEN' });
  if (!job) throw new ImageGenError('NOT_FOUND', 404);
  if (job.status === 'QUEUED') {
    await Job.updateOne({ _id: job._id, status: 'QUEUED' }, { $set: { status: 'CANCELLED', error: 'IMAGE_CANCELLED' } });
    await SceneImage.updateMany({ jobId: job._id, status: { $in: ['PENDING', 'GENERATING'] } }, { $set: { status: 'SKIPPED', error: 'IMAGE_CANCELLED' } });
  } else if (job.status === 'PROCESSING') {
    await Job.updateOne({ _id: job._id }, { $set: { 'payload.cancelRequested': true } });
  }
  return { cancelled: job.status === 'QUEUED' || job.status === 'PROCESSING' };
}

/** Saves a user-edited prompt for one scene's image. The Scene itself is not modified. */
export async function editImagePrompt(ownerId: mongoose.Types.ObjectId, sceneId: string, prompt: unknown) {
  if (!mongoose.isObjectIdOrHexString(sceneId)) throw new ImageGenError('NOT_FOUND', 404);
  const text = typeof prompt === 'string' ? prompt.normalize('NFC').replace(/\s+/g, ' ').trim() : '';
  if (text.length < 3 || text.length > 1000) throw new ImageGenError('IMAGE_PROMPT_INVALID');
  const image = await SceneImage.findOne({ sceneId, ownerId });
  if (!image) throw new ImageGenError('NOT_FOUND', 404);
  if (image.status === 'PENDING' || image.status === 'GENERATING') throw new ImageGenError('IMAGE_ALREADY_GENERATING', 409);
  image.prompt = text; image.promptEdited = true;
  await image.save();
  return image;
}

/** Images of a project for the workflow UI (no file paths, only an owner-checked URL). */
export async function projectImages(projectId: mongoose.Types.ObjectId) {
  const images = await SceneImage.find({ projectId }).sort({ order: 1 }).lean();
  return images.map((i) => ({
    sceneId: i.sceneId, order: i.order, status: i.status, preset: i.preset, seconds: i.seconds ?? null, cached: !!i.cached,
    downgradedFrom: i.downgradedFrom ?? null, error: i.error ?? null, prompt: i.prompt, promptEdited: i.promptEdited,
    url: i.status === 'READY' && i.file ? `/api/images/${i._id}/file?v=${i.attempt}-${new Date(i.updatedAt).getTime()}-${IMAGE_URL_REV}` : null,
    updatedAt: i.updatedAt,
  }));
}
